CREATE INDEX idx_reports_run_history ON integrity_reports(organization_id, run_id, analysis_revision, created_at, id);
CREATE UNIQUE INDEX idx_reports_job ON integrity_reports(organization_id, job_id) WHERE job_id IS NOT NULL;
CREATE TRIGGER integrity_report_ready_immutable BEFORE UPDATE ON integrity_reports WHEN OLD.status = 'ready' BEGIN SELECT RAISE(ABORT, 'immutable report'); END;
CREATE TRIGGER integrity_report_source_immutable BEFORE UPDATE ON integrity_reports WHEN OLD.source_json IS NOT NULL AND (NEW.source_json IS NOT OLD.source_json OR NEW.source_hash IS NOT OLD.source_hash OR NEW.frozen_at IS NOT OLD.frozen_at OR NEW.run_id != OLD.run_id OR NEW.organization_id != OLD.organization_id OR NEW.analysis_revision != OLD.analysis_revision OR NEW.schema_version != OLD.schema_version OR NEW.revision != OLD.revision OR NEW.format != OLD.format OR NEW.created_at != OLD.created_at OR NEW.created_by IS NOT OLD.created_by OR NEW.job_id IS NOT OLD.job_id) BEGIN SELECT RAISE(ABORT, 'immutable report source'); END;
